import{_ as a,o,c as t,a5 as r}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 5 话 响应式：一套代码，适配无穷屏幕","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.05-responsive.md","filePath":"comics/css/EP.05-responsive.md","lastUpdated":1793421609000}'),i={name:"comics/css/EP.05-responsive.md"};function s(l,e,n,c,h,d){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="漫画-·-第-5-话-响应式-一套代码-适配无穷屏幕" tabindex="-1">漫画 · 第 5 话 响应式：一套代码，适配无穷屏幕 <a class="header-anchor" href="#漫画-·-第-5-话-响应式-一套代码-适配无穷屏幕" aria-label="Permalink to &quot;漫画 · 第 5 话 响应式：一套代码，适配无穷屏幕&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/05-responsive">docs/css/05-responsive.md</a> ｜ 原画：<a href="./EP.05-responsive.svg">EP.05-responsive.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。页面在手机上被缩成蚂蚁字，气得跳脚——罪魁祸首是缺失的 viewport meta。</li><li><strong>标签君</strong>：HTML5 结构师，搬出&quot;响应式五层次&quot;金字塔，并演示同一张卡片放进侧栏、主区都能自动适配的容器查询。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>响应式的本质是&quot;一套代码适配无穷的浏览环境&quot;。像素酱先补上 viewport meta 这块地基，再学会移动优先的媒体查询姿势，最后用 clamp() 把字号从&quot;逐档跳变&quot;升级成&quot;连续流动&quot;，用容器查询让组件&quot;自带布局策略&quot;。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>没写 viewport meta 时，移动浏览器假定页面是 980px 宽的&quot;桌面页&quot;：先按 980px 渲染，再整体缩小塞进屏幕——字小如蚂蚁，手指点不准，一切响应式都无从谈起。<code>width=device-width</code> 把布局视口设为设备逻辑宽度，<code>initial-scale=1</code> 取消初始缩放，这是响应式的第一行代码。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>现代响应式是五个层次的叠加：viewport meta 定像素基准 → 媒体查询按设备切换 → clamp() 让字号连续流动 → 容器查询按组件容器宽度响应 → 逻辑属性与 srcset 管方向与资源。写法上坚持<strong>移动优先</strong>：基础样式给手机，宽了再用 <code>min-width</code> 增强；断点不照搬设备宽度表，而是插在&quot;当前设计开始变丑&quot;的地方。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p><code>clamp(1.5rem, 4vw + 1rem, 3rem)</code> 一行替代五档断点：字号随视口线性增长，两端被钳住——窄屏触底 1.5rem 不至于看不清，大屏封顶 3rem 不至于失控。容器查询则让组件自带布局策略：同一张卡片，放进 360px 的侧栏自动竖排，放进 720px 的主区自动横排，放哪都对。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>先写 viewport meta——没有它，移动端一切响应式都无从谈起。</li><li>移动优先：基础样式给手机，宽了再 min-width 增强；断点插在&quot;开始变丑&quot;处，不照搬设备表。</li><li>移动端 100vh 会被地址栏坑，用 100dvh；hover 效果包进 <code>(hover: hover)</code>，别在触屏上空等。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：手机上 <code>height: 100vh</code> 的全屏 Banner 为什么总&quot;高出一截&quot;？该换哪个单位？</p><p><strong>答</strong>：移动端地址栏收放会改变可视高度，而 100vh 按&quot;最大视口&quot;计算，包含被地址栏遮住的部分。换 <code>100dvh</code>（动态视口高度，实时跟随地址栏）即可；需要钉死两端时用 <code>svh</code>（最小）/<code>lvh</code>（最大）。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>媒体查询断点策略 + 视口单位 + clamp 流体排版：<a href="./../../examples/css/05-responsive/index-01-media-queries.html">examples/css/05-responsive/</a></li><li>容器查询组件化响应 + 逻辑属性与国际化：<a href="./../../examples/css/05-responsive/index-02-container-queries.html">index-02-container-queries.html</a></li><li>响应式图片与常用响应式布局模式：<a href="./../../examples/css/05-responsive/index-03-fluid-images-layout.html">index-03-fluid-images-layout.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 6 话《变量与 calc》——CSS 的&quot;运行时&quot;与&quot;计算器&quot;，改主题色不再全局搜索替换。</p>',22)])])}const m=a(i,[["render",s]]);export{p as __pageData,m as default};
